const data = $input.first().json;
if (!data.accessToken) throw new Error('Login failed: ' + JSON.stringify(data));
return [{ json: {
  accessToken: data.accessToken,
  refreshToken: data.refreshToken,
  expiresIn: data.expiresIn,
  runId: 'RUN-' + Date.now(),
  runStart: Date.now()
}}];

// ───────────────────────────────────────────────────────────────────────────
// PHASE A: Parse spec
// ───────────────────────────────────────────────────────────────────────────
const spec = $input.first().json;
const BASE_URL = $vars.AIRLINE_BASE_URL || 'http://localhost:3000';
const DEFAULT_SLA = 2000;

// Resolve $ref in the spec
function resolveRef(ref, s) {
  if (!ref || !ref.startsWith('#/')) return null;
  return ref.replace('#/', '').split('/').reduce((o, k) => o?.[k], s);
}
function deref(schema, s, depth = 0) {
  if (!schema || depth > 5) return schema || {};
  if (schema.$ref) return deref(resolveRef(schema.$ref, s), s, depth + 1);
  if (schema.allOf) return schema.allOf.reduce((m, x) => ({ ...m, ...deref(x, s, depth + 1) }), {});
  if (schema.oneOf || schema.anyOf) return deref((schema.oneOf || schema.anyOf)[0], s, depth + 1);
  if (schema.properties) {
    const props = {};
    for (const [k, v] of Object.entries(schema.properties)) props[k] = deref(v, s, depth + 1);
    return { ...schema, properties: props };
  }
  return schema;
}

// ───────────────────────────────────────────────────────────────────────────
// PHASE B: Generate a valid (positive) value from a schema node
// ───────────────────────────────────────────────────────────────────────────
function positiveVal(schema, name = '') {
  if (!schema) return 'value';
  if (schema.example !== undefined) return schema.example;
  switch (schema.type) {
    case 'integer': case 'number': {
      const mn = schema.minimum ?? 1, mx = schema.maximum ?? 99;
      return Math.round((mn + mx) / 2);
    }
    case 'boolean': return true;
    case 'array':   return [positiveVal(schema.items || { type: 'string' })];
    case 'object': {
      const o = {};
      for (const [k, v] of Object.entries(schema.properties || {})) o[k] = positiveVal(v, k);
      return o;
    }
    default: {
      if (schema.enum?.length) return schema.enum[0];
      if (schema.format === 'email')     return `test_${name || 'user'}@airline-test.com`;
      if (schema.format === 'date')      return '2024-08-15';
      if (schema.format === 'date-time') return '2024-08-15T08:00:00Z';
      const len = Math.min(Math.max(schema.minLength || 1, 6), schema.maxLength || 20);
      return (name || 'value').substring(0, len).padEnd(len, 'x');
    }
  }
}

function buildBody(bodySchema) {
  if (!bodySchema || (bodySchema.type !== 'object' && !bodySchema.properties)) return null;
  const b = {};
  for (const [k, v] of Object.entries(bodySchema.properties || {})) b[k] = positiveVal(v, k);
  return b;
}

function fillPath(path, vals) {
  return path.replace(/\{(\w+)\}/g, (_, n) => encodeURIComponent(vals[n] || `TEST_${n}`));
}

// Sensible airline ID seeds for path params
const PATH_SEEDS = { id: 'FL001', flightId: 'FL001', code: 'JFK', bookingId: 'BK001', passengerId: 'P001' };

// ───────────────────────────────────────────────────────────────────────────
// PHASE C: Generate test cases for every endpoint
// ───────────────────────────────────────────────────────────────────────────
const globalAuth = !!(spec.security?.length);
const testCases = [];

for (const [path, pathItem] of Object.entries(spec.paths || {})) {
  for (const [method, op] of Object.entries(pathItem)) {
    if (!['get','post','put','patch','delete'].includes(method)) continue;

    const requiresAuth = Object.prototype.hasOwnProperty.call(op, 'security')
      ? op.security?.length > 0
      : globalAuth;

    // Extract params
    const allParams = op.parameters || [];
    const pathParamNames = (path.match(/\{(\w+)\}/g) || []).map(m => m.slice(1, -1));
    const queryParams = allParams.filter(p => p.in === 'query');

    // Path param values
    const pathVals = {};
    for (const n of pathParamNames) pathVals[n] = PATH_SEEDS[n] || `TEST_${n}`;

    // Query param values (positive)
    const positiveQuery = {};
    for (const p of queryParams) positiveQuery[p.name] = p.example ?? positiveVal(deref(p.schema || {}, spec), p.name);
    if (path.includes('/flights/search')) {
      positiveQuery.origin = positiveQuery.origin || 'JFK';
      positiveQuery.destination = positiveQuery.destination || 'LHR';
      positiveQuery.date = positiveQuery.date || '2024-08-15';
    }

    // Body schema
    const rawBodySchema = op.requestBody?.content?.['application/json']?.schema;
    const bodySchema = rawBodySchema ? deref(rawBodySchema, spec) : null;
    const positiveBody = buildBody(bodySchema);

    const resolvedUrl = BASE_URL + fillPath(path, pathVals);
    const positiveStatus = Object.keys(op.responses || {}).map(Number).find(c => c >= 200 && c < 300) || 200;
    const AUTH = { Authorization: 'Bearer __ACCESS_TOKEN__' };
    const tag = `${method.toUpperCase()} ${path}`;

    function tc(overrides) {
      return {
        method: method.toUpperCase(), url: resolvedUrl,
        headers: requiresAuth ? AUTH : {},
        queryParams: positiveQuery,
        body: positiveBody,
        expectedStatus: positiveStatus,
        slaMs: DEFAULT_SLA,
        requiresAuth, type: 'positive', tag, ...overrides
      };
    }

    // 1. Positive
    testCases.push(tc({ id: `${tag}_positive`, type: 'positive', description: `[+] ${op.summary || tag}` }));

    // 2. Missing required body fields
    for (const f of bodySchema?.required || []) {
      const b = { ...positiveBody }; delete b[f];
      testCases.push(tc({ id: `${tag}_neg_missing_${f}`, type: 'negative', body: b, expectedStatus: 400, description: `[-] Missing '${f}' → 400` }));
    }

    // 3. Wrong type on first required field
    if (bodySchema?.required?.[0] && positiveBody) {
      const f = bodySchema.required[0];
      const wrongVal = bodySchema.properties?.[f]?.type === 'string' ? 99999 : null;
      testCases.push(tc({ id: `${tag}_neg_wrongtype_${f}`, type: 'negative', body: { ...positiveBody, [f]: wrongVal }, expectedStatus: 400, description: `[-] Wrong type for '${f}' → 400` }));
    }

    // 4. Boundary: string below minLength
    for (const [f, fs] of Object.entries(bodySchema?.properties || {}).filter(([, s]) => s.type === 'string' && s.minLength > 0).slice(0, 2)) {
      testCases.push(tc({ id: `${tag}_boundary_minLen_${f}`, type: 'boundary', body: { ...positiveBody, [f]: 'x'.repeat(Math.max(0, fs.minLength - 1)) }, expectedStatus: 400, description: `[B] '${f}' below minLength(${fs.minLength}) → 400` }));
      if (fs.maxLength) testCases.push(tc({ id: `${tag}_boundary_maxLen_${f}`, type: 'boundary', body: { ...positiveBody, [f]: 'x'.repeat(fs.maxLength + 1) }, expectedStatus: 400, description: `[B] '${f}' above maxLength(${fs.maxLength}) → 400` }));
    }

    // 5. Invalid path param → 404
    if (pathParamNames.length > 0) {
      const badVals = { ...pathVals, [pathParamNames[0]]: 'INVALID_XYZ_999' };
      testCases.push(tc({ id: `${tag}_neg_invalid_id`, type: 'negative', url: BASE_URL + fillPath(path, badVals), expectedStatus: 404, description: `[-] Invalid '${pathParamNames[0]}' → 404` }));
    }

    // 6. Missing required query params → 400
    if (queryParams.some(p => p.required)) {
      testCases.push(tc({ id: `${tag}_neg_missing_queryparam`, type: 'negative', queryParams: {}, expectedStatus: 400, description: `[-] Missing required query params → 400` }));
    }

    // 7. Auth: no token → 401
    if (requiresAuth) {
      testCases.push(tc({ id: `${tag}_auth_no_token`, type: 'auth', headers: {}, expectedStatus: 401, description: `[A] No token → 401` }));
      // 8. Auth: bad token → 403
      testCases.push(tc({ id: `${tag}_auth_bad_token`, type: 'auth', headers: { Authorization: 'Bearer invalid.jwt.garbage' }, expectedStatus: 403, description: `[A] Invalid JWT → 403` }));
    }
  }
}

const runId = $('Store Tokens').first().json.runId;
return [{ json: { testCases, total: testCases.length, runId, generatedAt: new Date().toISOString() } }];

// Split the testCases array into individual items for the loop
const { testCases, total, runId, generatedAt } = $input.first().json;
return testCases.map(tc => ({ json: { ...tc, _total: total, _runId: runId } }));

// Inject live access token into the Authorization header
const tc = $input.first().json;
const accessToken = $('Store Tokens').first().json.accessToken;

const headers = {};
for (const [k, v] of Object.entries(tc.headers || {})) {
  headers[k] = typeof v === 'string' ? v.replace('__ACCESS_TOKEN__', accessToken) : v;
}

return [{ json: { ...tc, headers, _accessToken: accessToken } }];

// Validate the response against the expected status and SLA
const tc = $('Inject Access Token').first().json;
const response = $input.first().json;

// n8n fullResponse gives: { status, headers, body }
const actualStatus = response.statusCode ?? response.status ?? null;
const responseBody = response.body ?? response;
const responseTimeMs = response.headers?.['x-response-time']
  ? parseInt(response.headers['x-response-time'])
  : (tc._responseTimeMs || 0);

const slaViolated = responseTimeMs > tc.slaMs;
const passed = actualStatus === tc.expectedStatus;

return [{ json: {
  testId: tc.id,
  type: tc.type,
  tag: tc.tag,
  description: tc.description,
  method: tc.method,
  url: tc.url,
  expectedStatus: tc.expectedStatus,
  actualStatus,
  passed,
  slaViolated,
  responseTimeMs,
  _runId: tc._runId,
  _total: tc._total,
  body: typeof responseBody === 'object' ? responseBody : { raw: responseBody }
}}];

// Update the stored token state with fresh tokens
const refreshData = $input.first().json;
if (!refreshData.accessToken) throw new Error('Token refresh failed: ' + JSON.stringify(refreshData));

// Mutate the Store Tokens node's output (n8n: write to static data)
$('Store Tokens').first().json.accessToken = refreshData.accessToken;
$('Store Tokens').first().json.refreshToken = refreshData.refreshToken;

return [{ json: { refreshed: true, newAccessToken: refreshData.accessToken } }];

// Build the final test report from all collected results
const allResults = $input.all().map(item => item.json);

const total = allResults.length;
const passed = allResults.filter(r => r.passed);
const failed = allResults.filter(r => !r.passed);
const slaVio = allResults.filter(r => r.slaViolated);
const passRate = total ? Math.round((passed.length / total) * 100) : 0;

const byType = allResults.reduce((acc, r) => {
  acc[r.type] = acc[r.type] || { pass: 0, fail: 0 };
  r.passed ? acc[r.type].pass++ : acc[r.type].fail++;
  return acc;
}, {});

const byEndpoint = allResults.reduce((acc, r) => {
  acc[r.tag] = acc[r.tag] || { pass: 0, fail: 0 };
  r.passed ? acc[r.tag].pass++ : acc[r.tag].fail++;
  return acc;
}, {});

const runId = allResults[0]?._runId || 'UNKNOWN';

const summary = {
  runId,
  completedAt: new Date().toISOString(),
  total,
  passed: passed.length,
  failed: failed.length,
  slaViolations: slaVio.length,
  passRate: passRate + '%',
  overallStatus: failed.length === 0 ? 'SUCCESS' : 'FAILURE',
  byType,
  byEndpoint
};

const failedDetails = failed.map(r => ({
  testId: r.testId,
  description: r.description,
  endpoint: `${r.method} ${r.url}`,
  expectedStatus: r.expectedStatus,
  actualStatus: r.actualStatus,
  slaViolated: r.slaViolated
}));

return [{ json: { summary, failedDetails, allResults, hasFailures: failed.length > 0 } }];

